/// A key label entry returned from [APIWallet::get_key_labels].
class APIKeyLabel {
  final String mfp;
  final String label;

  const APIKeyLabel({required this.mfp, required this.label});

  @override
  int get hashCode => mfp.hashCode ^ label.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is APIKeyLabel &&
          runtimeType == other.runtimeType &&
          mfp == other.mfp &&
          label == other.label;
}

