  const APIPathLabel({required this.rustId, required this.label});

  @override
  int get hashCode => rustId.hashCode ^ label.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is APIPathLabel &&
          runtimeType == other.runtimeType &&
          rustId == other.rustId &&
          label == other.label;
}
